import{_ as a,o as l,c as e,a2 as i}from"./chunks/framework.BbQrW5_t.js";const c=JSON.parse('{"title":"AI Agent 实战 - 引言知识点","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/00-introduction.md","filePath":"study/ai-agent-book/00-introduction.md","lastUpdated":1785465991000}'),r={name:"study/ai-agent-book/00-introduction.md"};function o(n,t,d,h,s,u){return l(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="ai-agent-实战-引言知识点" tabindex="-1">AI Agent 实战 - 引言知识点 <a class="header-anchor" href="#ai-agent-实战-引言知识点" aria-label="Permalink to &quot;AI Agent 实战 - 引言知识点&quot;">​</a></h1><hr><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="agent-核心公式" tabindex="-1">Agent 核心公式 <a class="header-anchor" href="#agent-核心公式" aria-label="Permalink to &quot;Agent 核心公式&quot;">​</a></h3><ul><li><strong>Agent = LLM + 上下文 + 工具</strong>（三者缺一不可）</li><li>三种理解层次： <ul><li>实现层：LLM + 上下文 + 工具</li><li>直觉层：大脑（思考决策）+ 眼睛（感知信息）+ 手脚（执行动作）</li><li>学术层：Policy（策略）+ Observation Space（观察空间）+ Action Space（动作空间）</li></ul></li></ul><h3 id="react-循环" tabindex="-1">ReAct 循环 <a class="header-anchor" href="#react-循环" aria-label="Permalink to &quot;ReAct 循环&quot;">​</a></h3><ul><li>思考 → 行动 → 观察的迭代过程</li><li>Agent 核心工作模式</li></ul><h3 id="关键架构概念" tabindex="-1">关键架构概念 <a class="header-anchor" href="#关键架构概念" aria-label="Permalink to &quot;关键架构概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>作用</th></tr></thead><tbody><tr><td>Skill</td><td>动态加载提示词，解决提示词无限膨胀问题</td></tr><tr><td>Harness</td><td>解决模型工具调用的不稳定、幻觉、危险操作等问题</td></tr><tr><td>Loop Engineering</td><td>通过提议者-审核者机制避免模型过早认为任务完成</td></tr></tbody></table><h3 id="技术术语区分" tabindex="-1">技术术语区分 <a class="header-anchor" href="#技术术语区分" aria-label="Permalink to &quot;技术术语区分&quot;">​</a></h3><ul><li><strong>Reasoning → &quot;思考&quot;</strong>：模型展开中间推导的过程</li><li><strong>Inference → &quot;推理&quot;</strong>：模型的前向计算与部署运行</li></ul><h3 id="关键技术栈" tabindex="-1">关键技术栈 <a class="header-anchor" href="#关键技术栈" aria-label="Permalink to &quot;关键技术栈&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>定义</th></tr></thead><tbody><tr><td>KV Cache</td><td>大模型推理中复用历史计算结果的机制</td></tr><tr><td>RAG</td><td>检索增强生成：先检索相关文档再让模型生成回答</td></tr><tr><td>Agentic RAG</td><td>让 Agent 自主决定何时检索、检索什么</td></tr><tr><td>MCP</td><td>工具互操作标准</td></tr><tr><td>SFT</td><td>监督微调：用标注数据教模型&quot;照样学样&quot;</td></tr><tr><td>RL</td><td>强化学习：让模型通过试错和奖励反馈自主提升</td></tr><tr><td>VLA</td><td>视觉-语言-动作模型：控制机器人操作</td></tr><tr><td>Sim2Real</td><td>从仿真环境迁移到真实环境</td></tr></tbody></table><hr><h2 id="关键观点" tabindex="-1">关键观点 <a class="header-anchor" href="#关键观点" aria-label="Permalink to &quot;关键观点&quot;">​</a></h2><h3 id="_1-实践在前-命名在后" tabindex="-1">1. 实践在前，命名在后 <a class="header-anchor" href="#_1-实践在前-命名在后" aria-label="Permalink to &quot;1. 实践在前，命名在后&quot;">​</a></h3><ul><li>不是 Anthropic 先发明概念，Agent 才跟着用</li><li>而是大量 Agent 早就在这么做，才被提炼成架构设计原则</li><li><strong>启示</strong>：等名词流行才去实践，已经慢了一步</li></ul><h3 id="_2-好的设计原则穿越模型迭代周期" tabindex="-1">2. 好的设计原则穿越模型迭代周期 <a class="header-anchor" href="#_2-好的设计原则穿越模型迭代周期" aria-label="Permalink to &quot;2. 好的设计原则穿越模型迭代周期&quot;">​</a></h3><ul><li>原则描述的不是某个模型的用法，而是智能系统与世界交互的基本模式</li><li>不因底层模型升级、产品形态创新而改变</li></ul><h3 id="_3-没有评估-就没有进步" tabindex="-1">3. 没有评估，就没有进步 <a class="header-anchor" href="#_3-没有评估-就没有进步" aria-label="Permalink to &quot;3. 没有评估，就没有进步&quot;">​</a></h3><ul><li>评估是科学方法论的地基</li><li>让 Agent 迭代方向不再依赖直觉，而是基于数据</li></ul><h3 id="_4-sft-记忆、rl-泛化" tabindex="-1">4. SFT 记忆、RL 泛化 <a class="header-anchor" href="#_4-sft-记忆、rl-泛化" aria-label="Permalink to &quot;4. SFT 记忆、RL 泛化&quot;">​</a></h3><ul><li>SFT 学会具体模式，RL 提升泛化能力</li><li>数据与环境比算法更重要</li></ul><h3 id="_5-coding-agent-文件系统是通用-agent-的核心技术基础" tabindex="-1">5. Coding Agent + 文件系统是通用 Agent 的核心技术基础 <a class="header-anchor" href="#_5-coding-agent-文件系统是通用-agent-的核心技术基础" aria-label="Permalink to &quot;5. Coding Agent + 文件系统是通用 Agent 的核心技术基础&quot;">​</a></h3><ul><li>代码生成不仅用于编程，还可辅助思考、构建知识库、动态创造新工具</li><li>是 Agent 自举的关键</li></ul><h3 id="_6-agent-是宇宙演化的新阶段" tabindex="-1">6. Agent 是宇宙演化的新阶段 <a class="header-anchor" href="#_6-agent-是宇宙演化的新阶段" aria-label="Permalink to &quot;6. Agent 是宇宙演化的新阶段&quot;">​</a></h3><ul><li>Richard Sutton：宇宙演化经历了 尘埃 → 恒星 → 生命 → 智能体 四个阶段</li><li>Agent 能理解自身运作机制，通过生成代码实现自举和自我进化</li></ul><hr><h2 id="实践要点" tabindex="-1">实践要点 <a class="header-anchor" href="#实践要点" aria-label="Permalink to &quot;实践要点&quot;">​</a></h2><h3 id="构建可靠-agent-的关键方法" tabindex="-1">构建可靠 Agent 的关键方法 <a class="header-anchor" href="#构建可靠-agent-的关键方法" aria-label="Permalink to &quot;构建可靠 Agent 的关键方法&quot;">​</a></h3><ol><li><p><strong>动态加载提示词</strong></p><ul><li>解决提示词无限膨胀问题</li><li>按需加载 Skills</li></ul></li><li><p><strong>命令行执行工具</strong></p><ul><li>解决工具列表无限膨胀问题</li></ul></li><li><p><strong>系统状态栏技术</strong></p><ul><li>让 Agent 感知执行环境、用户时间、工作状态</li></ul></li><li><p><strong>Harness 机制</strong></p><ul><li>解决模型工具调用的不稳定、幻觉、危险操作、越权操作、指令不遵循等问题</li></ul></li><li><p><strong>提议者-审核者方法</strong></p><ul><li>解决模型过早认为任务完成的问题</li></ul></li></ol><h3 id="获得前瞻性能力的两个关键" tabindex="-1">获得前瞻性能力的两个关键 <a class="header-anchor" href="#获得前瞻性能力的两个关键" aria-label="Permalink to &quot;获得前瞻性能力的两个关键&quot;">​</a></h3><ol><li><p><strong>拥有对 Agent 能力上限有极高要求的真实业务</strong></p><ul><li>持续获得真实业务反馈</li><li>足够复杂的场景才会倒逼架构优化</li></ul></li><li><p><strong>建立评估机制</strong></p><ul><li>分辨改动是真好还是运气</li><li>让迭代方向不依赖直觉</li></ul></li></ol><h3 id="全书四层次架构" tabindex="-1">全书四层次架构 <a class="header-anchor" href="#全书四层次架构" aria-label="Permalink to &quot;全书四层次架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>章节</th><th>内容</th></tr></thead><tbody><tr><td>第一层</td><td>第一章</td><td>Agent 基础框架</td></tr><tr><td>第二层</td><td>第二至五章</td><td>构建 Agent（上下文 → 知识 → 工具 → 代码生成）</td></tr><tr><td>第三层</td><td>第六至八章</td><td>评估与改进（度量 → 后训练 → 持续进化）</td></tr><tr><td>第四层</td><td>第九至十章</td><td>扩展（多模态交互 → 多 Agent 协作）</td></tr></tbody></table><hr><h2 id="扩展思考" tabindex="-1">扩展思考 <a class="header-anchor" href="#扩展思考" aria-label="Permalink to &quot;扩展思考&quot;">​</a></h2><h3 id="阅读路径建议" tabindex="-1">阅读路径建议 <a class="header-anchor" href="#阅读路径建议" aria-label="Permalink to &quot;阅读路径建议&quot;">​</a></h3><ul><li><strong>Agent 开发者</strong>：顺序阅读第一至八章</li><li><strong>时间有限</strong>：优先第一章（全局认知）+ 第二章（上下文工程）</li><li><strong>关注模型训练</strong>：第七章（后训练）+ 第六章（评估）</li></ul><h3 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h3><p><strong>必需</strong>：</p><ul><li>Python 编程基础</li><li>LLM 基本使用经验</li><li>AI 辅助编程工具（Claude Code、Cursor 等）</li><li>软件工程常识（命令行、Git、JSON、REST API）</li></ul><p><strong>推荐（特定章节）</strong>：</p><ul><li>机器学习基础（第七章）</li><li>基础数学：线性代数、概率统计（第 2-3、7 章）</li><li>Web 开发基础（第 4、9 章）</li><li>Transformer 架构理解（第 2、7 章）</li></ul><h3 id="核心价值定位" tabindex="-1">核心价值定位 <a class="header-anchor" href="#核心价值定位" aria-label="Permalink to &quot;核心价值定位&quot;">​</a></h3><ul><li>不是教某个具体算法，而是架构设计原则和工程实践方法论</li><li>除第七章外，对数学和机器学习要求低</li><li>强调动手实验（配套代码仓库：<a href="https://github.com/bojioli/ai-agent-book%EF%BC%89" target="_blank" rel="noreferrer">https://github.com/bojioli/ai-agent-book）</a></li></ul><h3 id="术语约定" tabindex="-1">术语约定 <a class="header-anchor" href="#术语约定" aria-label="Permalink to &quot;术语约定&quot;">​</a></h3><ul><li>reasoning → 思考（思考链、思考模型、思考 token）</li><li>inference → 推理（推理时、推理成本、推理栈）</li><li>例外：逻辑推理、多跳推理、空间推理、时序推理保留习惯译法</li></ul><hr><p><strong>来源</strong>：《AI Agent 实战》引言 <strong>作者</strong>：Pine AI 团队 <strong>开源地址</strong>：<a href="https://github.com/bojieli/ai-agent-book" target="_blank" rel="noreferrer">https://github.com/bojieli/ai-agent-book</a></p>',50)])])}const b=a(r,[["render",o]]);export{c as __pageData,b as default};
